{"command":"python3 << 'EOF'
import csv

with open('outputs/t08_pois_clean.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)

print(f"Header: {rows[0]}")
print(f"Total data rows: {len(rows) - 1}")

# Verify each row has exactly 6 fields
all_ok = True
for i, row in enumerate(rows, 1):
    if len(row) != 6:
        print(f"Row {i} has {len(row)} columns, expected 6")
        all_ok = False
    # Check that all fields are properly quoted if needed
    for j, field in enumerate(row):
        if ',' in field and not (field.startswith('"') and field.endswith('"')):
            print(f"Row {i}, field {j+1}: contains comma but not quoted: '{field}'")
            all_ok = False

if all_ok:
    print("All rows have 6 fields and are RFC 4180 compliant")
else:
    print("Some issues found")
EOF"}
